(function(){
  function toFull(s){ return String(s).replace(/[\x20-\x7E]/g, function(c){ var code=c.charCodeAt(0); if(code===0x20) return '　'; return String.fromCharCode(code+0xFEE0); }); }
  function toHalf(s){ return String(s).replace(/[\uFF01-\uFF5E]/g, function(c){ return String.fromCharCode(c.charCodeAt(0)-0xFEE0); }).replace(/　/g,' '); }
  var API={toFull:toFull,toHalf:toHalf};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__ZenkakuForge__=API;
})();
